/**
 * Word Rush association graph.
 *
 * Editorial content written for Curious Minds. Two words are a valid link when
 * they share a cluster below, or when LINKS joins them directly. Clusters are
 * written as comma-separated strings for readability and split at load time.
 */
import type { AssociationCluster, AssociationLink } from './types';

function c(id: string, label: string, words: string): AssociationCluster {
  return {
    id,
    label,
    words: words
      .split(',')
      .map((w) => w.trim())
      .filter((w) => w.length > 0),
  };
}

