/** Merge the link lists, keeping the first note when a pair appears twice. */
function mergeLinks(...lists: AssociationLink[][]): AssociationLink[] {
  const seen = new Set<string>();
  const out: AssociationLink[] = [];
  for (const list of lists) {
    for (const link of list) {
      const key = [link[0], link[1]].sort().join('|');
      if (link[0] === link[1] || seen.has(key)) continue;
      seen.add(key);
      out.push(link);
    }
  }
  return out;
}

export const LINKS: AssociationLink[] = mergeLinks(
  PAIRS,
  OPPOSITES.map(([a, b]): AssociationLink => [a, b, 'opposites']),
  COMPOUNDS,
);

